      "arFull": "زُیِّنَ لِلنَّاسِ حُبُّ الشَّهَوٰتِ مِنَ النِّسَآءِ وَالْبَنِیْنَ وَالْقَنَاطِیْرِ الْمُقَنْطَرَةِ مِنَ الذَّهَبِ وَالْفِضَّةِ وَالْخَیْلِ الْمُسَوَّمَةِ وَالْاَنْعَامِ وَالْحَرْثِ ؕ ذٰلِكَ مَتَاعُ الْحَیٰوةِ الدُّنْیَا ۚ وَاللّٰهُ عِنْدَهٗ حُسْنُ الْمَاٰبِ ۟",
      "ur": "مرغوب چیزوں کی محبت لوگوں کے لئے مزین کر دی گئی ہے، جیسے عورتیں اور بیٹے اور سونے اور چاندی کے جمع کئے ہوئے خزانے اور نشاندار گھوڑے اور چوپائے اور کھیتی[1] ، یہ دنیا کی زندگی کا سامان ہے اور لوٹنے کا اچھا ٹھکانا تو اللہ تعالیٰ ہی کے پاس ہے۔",
      "en": "Beautified for people is the love of that which they desire - of women and sons, heaped-up sums of gold and silver, fine branded horses, and cattle and tilled land. That is the enjoyment of worldly life, but Allāh has with Him the best return [i.e., Paradise].",
