      "arFull": "اَلَّذِیْنَ یَقُوْلُوْنَ رَبَّنَاۤ اِنَّنَاۤ اٰمَنَّا فَاغْفِرْ لَنَا ذُنُوْبَنَا وَقِنَا عَذَابَ النَّارِ ۟ۚ",
