      "arFull": "فَاِنْ حَآجُّوْكَ فَقُلْ اَسْلَمْتُ وَجْهِیَ لِلّٰهِ وَمَنِ اتَّبَعَنِ ؕ وَقُلْ لِّلَّذِیْنَ اُوْتُوا الْكِتٰبَ وَالْاُمِّیّٖنَ ءَاَسْلَمْتُمْ ؕ فَاِنْ اَسْلَمُوْا فَقَدِ اهْتَدَوْا ۚ وَاِنْ تَوَلَّوْا فَاِنَّمَا عَلَیْكَ الْبَلٰغُ ؕ وَاللّٰهُ بَصِیْرٌ بِالْعِبَادِ ۟۠",
      "ur": "پھر بھی اگر یہ آپ سے جھگڑیں توآپ کہہ دیں کہ میں اور میرے تابعداروں نے اللہ تعالیٰ کے سامنے اپنا سر تسلیم خم کر دیا ہے اور اہل کتاب سے اور انپڑھ لوگوں[1] سے کہہ دیجیئے! کہ کیا تم بھی اطاعت کرتے ہو؟ پس اگر یہ بھی تابعدار بن جائیں تو یقیناً ہداہت والے ہیں اور اگر یہ روگردانی کریں، تو آپ پر صرف پہنچا دینا ہے اور اللہ بندوں کو خوب دیکھ بھال رہا ہے۔",
