      "arFull": "اَلَمْ تَرَ اِلَی الَّذِیْنَ اُوْتُوْا نَصِیْبًا مِّنَ الْكِتٰبِ یُدْعَوْنَ اِلٰی كِتٰبِ اللّٰهِ لِیَحْكُمَ بَیْنَهُمْ ثُمَّ یَتَوَلّٰی فَرِیْقٌ مِّنْهُمْ وَهُمْ مُّعْرِضُوْنَ ۟",
