      "arFull": "ذٰلِكَ بِاَنَّهُمْ قَالُوْا لَنْ تَمَسَّنَا النَّارُ اِلَّاۤ اَیَّامًا مَّعْدُوْدٰتٍ ۪ وَغَرَّهُمْ فِیْ دِیْنِهِمْ مَّا كَانُوْا یَفْتَرُوْنَ ۟",
