      "arFull": "اِنَّ اللّٰهَ اصْطَفٰۤی اٰدَمَ وَنُوْحًا وَّاٰلَ اِبْرٰهِیْمَ وَاٰلَ عِمْرٰنَ عَلَی الْعٰلَمِیْنَ ۟ۙ",
