      "arFull": "فَنَادَتْهُ الْمَلٰٓىِٕكَةُ وَهُوَ قَآىِٕمٌ یُّصَلِّیْ فِی الْمِحْرَابِ ۙ اَنَّ اللّٰهَ یُبَشِّرُكَ بِیَحْیٰی مُصَدِّقًا بِكَلِمَةٍ مِّنَ اللّٰهِ وَسَیِّدًا وَّحَصُوْرًا وَّنَبِیًّا مِّنَ الصّٰلِحِیْنَ ۟",
