      "arFull": "وَاِذْ قَالَتِ الْمَلٰٓىِٕكَةُ یٰمَرْیَمُ اِنَّ اللّٰهَ اصْطَفٰىكِ وَطَهَّرَكِ وَاصْطَفٰىكِ عَلٰی نِسَآءِ الْعٰلَمِیْنَ ۟",
