      "arFull": "ذٰلِكَ مِنْ اَنْۢبَآءِ الْغَیْبِ نُوْحِیْهِ اِلَیْكَ ؕ وَمَا كُنْتَ لَدَیْهِمْ اِذْ یُلْقُوْنَ اَقْلَامَهُمْ اَیُّهُمْ یَكْفُلُ مَرْیَمَ ۪ وَمَا كُنْتَ لَدَیْهِمْ اِذْ یَخْتَصِمُوْنَ ۟",
