      "number": 70,
      "arFull": "یٰۤاَهْلَ الْكِتٰبِ لِمَ تَكْفُرُوْنَ بِاٰیٰتِ اللّٰهِ وَاَنْتُمْ تَشْهَدُوْنَ ۟",
