      "arFull": "وَمِنْ اَهْلِ الْكِتٰبِ مَنْ اِنْ تَاْمَنْهُ بِقِنْطَارٍ یُّؤَدِّهٖۤ اِلَیْكَ ۚ وَمِنْهُمْ مَّنْ اِنْ تَاْمَنْهُ بِدِیْنَارٍ لَّا یُؤَدِّهٖۤ اِلَیْكَ اِلَّا مَا دُمْتَ عَلَیْهِ قَآىِٕمًا ؕ ذٰلِكَ بِاَنَّهُمْ قَالُوْا لَیْسَ عَلَیْنَا فِی الْاُمِّیّٖنَ سَبِیْلٌ ۚ وَیَقُوْلُوْنَ عَلَی اللّٰهِ الْكَذِبَ وَهُمْ یَعْلَمُوْنَ ۟",
