      "arFull": "اِلَّا الَّذِیْنَ تَابُوْا مِنْ بَعْدِ ذٰلِكَ وَاَصْلَحُوْا ۫ فَاِنَّ اللّٰهَ غَفُوْرٌ رَّحِیْمٌ ۟",
