      "arFull": "اِنَّ الَّذِیْنَ كَفَرُوْا وَمَاتُوْا وَهُمْ كُفَّارٌ فَلَنْ یُّقْبَلَ مِنْ اَحَدِهِمْ مِّلْءُ الْاَرْضِ ذَهَبًا وَّلَوِ افْتَدٰی بِهٖ ؕ اُولٰٓىِٕكَ لَهُمْ عَذَابٌ اَلِیْمٌ وَّمَا لَهُمْ مِّنْ نّٰصِرِیْنَ ۟۠",
