      "arFull": "لَنْ تَنَالُوا الْبِرَّ حَتّٰی تُنْفِقُوْا مِمَّا تُحِبُّوْنَ ؕ۬ وَمَا تُنْفِقُوْا مِنْ شَیْءٍ فَاِنَّ اللّٰهَ بِهٖ عَلِیْمٌ ۟",
