      "arFull": "قُلْ صَدَقَ اللّٰهُ ۫ فَاتَّبِعُوْا مِلَّةَ اِبْرٰهِیْمَ حَنِیْفًا ؕ وَمَا كَانَ مِنَ الْمُشْرِكِیْنَ ۟",
      "ur": "کہہ دیجئے کہ اللہ تعالیٰ سچا ہے تم سب ابراہیم حنیف کے ملت کی پیروی کرو، جو مشرک نہ تھے.",
