      "number": 106,
      "arFull": "یَّوْمَ تَبْیَضُّ وُجُوْهٌ وَّتَسْوَدُّ وُجُوْهٌ ۚ فَاَمَّا الَّذِیْنَ اسْوَدَّتْ وُجُوْهُهُمْ ۫ اَكَفَرْتُمْ بَعْدَ اِیْمَانِكُمْ فَذُوْقُوا الْعَذَابَ بِمَا كُنْتُمْ تَكْفُرُوْنَ ۟",
      "ur": "جس دن بعض چہرے سفید ہوں گے اور بعض سیاه[1] ، سیاه چہرے والوں (سے کہا جائے گا) کہ کیا تم نے ایمان ﻻنے کے بعد کفر کیا؟ اب اپنے کفر کا عذاب چکھو.",
      "en": "On the Day [some] faces will turn white and [some] faces will turn black. As for those whose faces turn black, [to them it will be said], \"Did you disbelieve [i.e., reject faith] after your belief? Then taste the punishment for what you used to reject.\"",
