      "arFull": "وَاَمَّا الَّذِیْنَ ابْیَضَّتْ وُجُوْهُهُمْ فَفِیْ رَحْمَةِ اللّٰهِ ؕ هُمْ فِیْهَا خٰلِدُوْنَ ۟",
