      "number": 122,
      "arFull": "اِذْ هَمَّتْ طَّآىِٕفَتٰنِ مِنْكُمْ اَنْ تَفْشَلَا ۙ وَاللّٰهُ وَلِیُّهُمَا ؕ وَعَلَی اللّٰهِ فَلْیَتَوَكَّلِ الْمُؤْمِنُوْنَ ۟",
      "ur": "جب تمہاری دو جماعتیں پست ہمتی کا اراده کر چکی تھیں[1] ، اللہ تعالیٰ انکا ولی اور مددگار ہے[2]۔ اور اسی کی پاک ذات پر مومنوں کو بھروسہ رکھنا چاہئے.",
