      "arFull": "سَنُلْقِیْ فِیْ قُلُوْبِ الَّذِیْنَ كَفَرُوا الرُّعْبَ بِمَاۤ اَشْرَكُوْا بِاللّٰهِ مَا لَمْ یُنَزِّلْ بِهٖ سُلْطٰنًا ۚ وَمَاْوٰىهُمُ النَّارُ ؕ وَبِئْسَ مَثْوَی الظّٰلِمِیْنَ ۟",
      "ur": "ہم عنقریب کافروں کے دلوں میں رعب ڈال دیں گے، اس وجہ سے کہ یہ اللہ کے ساتھ ان چیزوں کو شریک کرتے ہیں جس کی کوئی دلیل اللہ نے نہیں اتاری[1] ، ان کا ٹھکانہ جہنم ہے، اور ان ﻇالموں کی بری جگہ ہے.",
