      "arFull": "وَلِیَعْلَمَ الَّذِیْنَ نَافَقُوْا ۖۚ وَقِیْلَ لَهُمْ تَعَالَوْا قَاتِلُوْا فِیْ سَبِیْلِ اللّٰهِ اَوِ ادْفَعُوْا ؕ قَالُوْا لَوْ نَعْلَمُ قِتَالًا لَّاتَّبَعْنٰكُمْ ؕ هُمْ لِلْكُفْرِ یَوْمَىِٕذٍ اَقْرَبُ مِنْهُمْ لِلْاِیْمَانِ ۚ یَقُوْلُوْنَ بِاَفْوَاهِهِمْ مَّا لَیْسَ فِیْ قُلُوْبِهِمْ ؕ وَاللّٰهُ اَعْلَمُ بِمَا یَكْتُمُوْنَ ۟ۚ",
      "ur": "اور منافقوں کو بھی معلوم کر لے[1] جن سے کہا گیا کہ آؤ اللہ کی راه میں جہاد کرو، یا کافروں کو ہٹاو، ٴ تو وه کہنے لگے کہ اگر ہم لڑائی جانتے ہوتے تو ضرور ساتھ دیتے[2]، وه اس دن بہ نسبت ایمان کے کفر سے بہت قریب تھے[3]، اپنے منھ سے وه باتیں بناتے ہیں جو ان کے دلوں میں نہیں[4]، اور اللہ تعالیٰ خوب جانتا ہے جسے وه چھپاتے ہیں.",
      "en": "And that He might make evident those who are hypocrites. For it was said to them, \"Come, fight in the way of Allāh or [at least] defend.\" They said, \"If we had known [there would be] battle, we would have followed you.\" They were nearer to disbelief that day than to faith, saying with their mouths what was not in their hearts. And Allāh is most knowing of what they conceal -",
