      "number": 179,
      "arFull": "مَا كَانَ اللّٰهُ لِیَذَرَ الْمُؤْمِنِیْنَ عَلٰی مَاۤ اَنْتُمْ عَلَیْهِ حَتّٰی یَمِیْزَ الْخَبِیْثَ مِنَ الطَّیِّبِ ؕ وَمَا كَانَ اللّٰهُ لِیُطْلِعَكُمْ عَلَی الْغَیْبِ وَلٰكِنَّ اللّٰهَ یَجْتَبِیْ مِنْ رُّسُلِهٖ مَنْ یَّشَآءُ ۪ فَاٰمِنُوْا بِاللّٰهِ وَرُسُلِهٖ ۚ وَاِنْ تُؤْمِنُوْا وَتَتَّقُوْا فَلَكُمْ اَجْرٌ عَظِیْمٌ ۟",
      "ur": "جس حال میں تم ہو اسی پر اللہ ایمان والوں کو نہ چھوڑ دے گا جب تک کہ پاک اور ناپاک کو الگ الگ نہ کر دے[1] ، اور نہ اللہ تعالیٰ ایسا ہے کہ تمہیں غیب سے آگاه کردے[2]، بلکہ اللہ تعالیٰ اپنے رسولوں میں سے جس کا چاہے انتخاب کر لیتا ہے[3]، اس لئے تم اللہ تعالیٰ پر اور اس کے رسولوں پر ایمان رکھو، اگر تم ایمان ﻻؤ اور تقویٰ کرو تو تمہارے لئے بڑا بھاری اجر ہے.",
