      "arFull": "اَلَّذِیْنَ قَالُوْۤا اِنَّ اللّٰهَ عَهِدَ اِلَیْنَاۤ اَلَّا نُؤْمِنَ لِرَسُوْلٍ حَتّٰی یَاْتِیَنَا بِقُرْبَانٍ تَاْكُلُهُ النَّارُ ؕ قُلْ قَدْ جَآءَكُمْ رُسُلٌ مِّنْ قَبْلِیْ بِالْبَیِّنٰتِ وَبِالَّذِیْ قُلْتُمْ فَلِمَ قَتَلْتُمُوْهُمْ اِنْ كُنْتُمْ صٰدِقِیْنَ ۟",
      "ur": "یہ وه لوگ ہیں جنہوں نے کہا کہ اللہ تعالیٰ نے ہمیں حکم دیا ہے کہ کسی رسول کو نہ مانیں جب تک وه ہمارے پاس ایسی قربانی نہ ﻻئے جسے آگ کھا جائے۔ آپ کہہ دیجئے کہ اگر تم سچے ہو تو مجھ سے پہلے تمہارے پاس جو رسول دیگر معجزوں کے ساتھ یہ بھی ﻻئے جسے تم کہہ رہے ہو تو پھر تم نے انہیں کیوں مار ڈاﻻ؟[1]",
      "en": "[They are] those who said, \"Indeed, Allāh has taken our promise not to believe any messenger until he brings us an offering which fire [from heaven] will consume.\" Say, \"There have already come to you messengers before me with clear proofs and [even] that of which you speak. So why did you kill them, if you should be truthful?\"",
