      "arFull": "رَبَّنَا وَاٰتِنَا مَا وَعَدْتَّنَا عَلٰی رُسُلِكَ وَلَا تُخْزِنَا یَوْمَ الْقِیٰمَةِ ؕ اِنَّكَ لَا تُخْلِفُ الْمِیْعَادَ ۟",
