      "arFull": "لٰكِنِ الَّذِیْنَ اتَّقَوْا رَبَّهُمْ لَهُمْ جَنّٰتٌ تَجْرِیْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِیْنَ فِیْهَا نُزُلًا مِّنْ عِنْدِ اللّٰهِ ؕ وَمَا عِنْدَ اللّٰهِ خَیْرٌ لِّلْاَبْرَارِ ۟",
